insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welcher Zahnradschaden ist abgebildet?$q$, $q$Which gear failure is shown?$q$, $q$img/foto_schaden_ermuedungsbruch.jpg$q$, $q$Quelle im Skript nicht angegeben · Skript FME, Folie 70$q$, $q$[{"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Dauerbruch (Ermüdungsbruch)|fatigue breakage}}", "en": "{{Fatigue breakage|Dauerbruch (Ermüdungsbruch)}}"}, {"de": "{{Gewaltbruch|forced breakage}}", "en": "{{Forced breakage|Gewaltbruch}}"}, {"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}]$q$::jsonb, $q$1$q$::jsonb, $q${{Dauerbruch (Ermüdungsbruch)|fatigue breakage}}: Der Riss wächst langsam vom {{Zahnfuß|tooth root}} aus; typisch ist die glatte Ermüdungsfläche mit Restgewaltbruch.$q$, $q${{Fatigue breakage|Dauerbruch (Ermüdungsbruch)}}: the crack grows slowly from the {{tooth root|Zahnfuß}}; typical is the smooth fatigue surface with a final forced fracture.$q$);
