if not exists (select 1 from public.questions where image = $q$img/foto_schaden_gewaltbruch.jpg$q$) then
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welcher Zahnradschaden ist abgebildet?$q$, $q$Which gear failure is shown?$q$, $q$img/foto_schaden_gewaltbruch.jpg$q$, $q$Quelle im Skript nicht angegeben · Skript FME, Folie 70$q$, $q$[{"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Dauerbruch (Ermüdungsbruch)|fatigue breakage}}", "en": "{{Fatigue breakage|Dauerbruch (Ermüdungsbruch)}}"}, {"de": "{{Gewaltbruch|forced breakage}}", "en": "{{Forced breakage|Gewaltbruch}}"}, {"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}]$q$::jsonb, $q$2$q$::jsonb, $q${{Gewaltbruch|forced breakage}}: Der Zahn bricht durch Überlast (z. B. Unfall, Blockieren). Die Bruchfläche ist zerklüftet. Dieser Fall ist nicht durch die Normen abgedeckt.$q$, $q${{Forced breakage|Gewaltbruch}}: the tooth breaks due to overload (e.g. accident, jamming). The fracture surface is rough. This case is not covered by the standards.$q$);
