if not exists (select 1 from public.questions where image = $q$img/foto_schaden_fressen.jpg$q$) then
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welcher Zahnradschaden ist abgebildet?$q$, $q$Which gear failure is shown?$q$, $q$img/foto_schaden_fressen.jpg$q$, $q$TU München, FZG · Skript FME, Folie 71$q$, $q$[{"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Dauerbruch (Ermüdungsbruch)|fatigue breakage}}", "en": "{{Fatigue breakage|Dauerbruch (Ermüdungsbruch)}}"}, {"de": "{{Gewaltbruch|forced breakage}}", "en": "{{Forced breakage|Gewaltbruch}}"}, {"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}]$q$::jsonb, $q$3$q$::jsonb, $q${{Fressen|scuffing}}: Riefen in Gleitrichtung durch kurzzeitiges Verschweißen und Aufreißen der Flanken, weil der Schmierfilm thermisch versagt.$q$, $q${{Scuffing|Fressen}}: scores in the sliding direction from flanks briefly welding and tearing apart, because the lubricant film fails thermally.$q$);
