insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welcher Zahnradschaden ist abgebildet?$q$, $q$Which gear failure is shown?$q$, $q$img/foto_schaden_graufleckigkeit.jpg$q$, $q$TU München, FZG · Skript FME, Folie 71$q$, $q$[{"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Dauerbruch (Ermüdungsbruch)|fatigue breakage}}", "en": "{{Fatigue breakage|Dauerbruch (Ermüdungsbruch)}}"}, {"de": "{{Gewaltbruch|forced breakage}}", "en": "{{Forced breakage|Gewaltbruch}}"}, {"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}]$q$::jsonb, $q$4$q$::jsonb, $q${{Graufleckigkeit|micropitting}}: matte, grau schimmernde Flächen durch Mikroermüdung an den Rauheitsspitzen. Sie kann Grübchen begünstigen.$q$, $q${{Micropitting|Graufleckigkeit}}: matt, grey shaded areas from micro-fatigue at the roughness peaks. It can promote pitting.$q$);
